Sometimes we may want to get the underlying dbus connection's status.

A simple `Connection` method is introduced for re-using the connection 

```go
var globalConn = dbus.NewSystemdConnectionContext(ctx)

func getConn() *Conn {
   if globalConn.Connected() {
      // refresh the connection
      globalConn = dbus.NewSystemdConnectionContext(ctx)
   }

   return globalConn
}

func main() {
     getConn().xxx()

    // between the two use of the getConn, somethings may happen to break the connection
    // e.g.: systemctl daemon-reexec

    getConn().xxx()
}

```

And the underlying `sysconn` and `sigconn` are also exported in this PR. A typical usage is in Subscription

```
func main() {
    for {
        conn := dbus.NewSystemdConnectionContext(context.Background())

        conn.Subscribe()
        sets := conn.NewSubscriptionSet()
        changes, errs := sets.Subscribe()

        for {
          select {
          case change := <-changes:
              // ...
          case err := <-errs:
             // ...
          case <- conn.SigConn().Context().Done():
             continue
          case <- conn.SysConn().Context().Done():
             continue
          }
      }
    }

}

```

